WITH with_windows AS (SELECT *, AVG(monthly_fee) OVER (PARTITION BY status, customer_id ORDER BY monthly_fee, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS monthly_fee_avg_5_prior, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY monthly_fee, id) AS row_seq FROM subscriptions) SELECT CASE WHEN monthly_fee >= 206 THEN 'HIGH' ELSE 'LOW' END AS monthly_fee_tier, DATE_TRUNC('MONTH', end_date) AS activity_month, APPROX_PERCENTILE(row_seq, ARRAY(0.25, 0.5, 0.75)) AS row_seq_quartiles, SUM(CASE WHEN plan = 'premium' THEN row_seq ELSE 0 END) AS premium_row_seq, MIN(monthly_fee) AS min_monthly_fee, SIZE(COLLECT_SET(plan)) AS num_plans, COUNT(CASE WHEN plan = 'standard' THEN 1 END) AS standard_count, ROUND(AVG(monthly_fee_avg_5_prior), 2) AS avg_monthly_fee_avg_5_prior FROM with_windows GROUP BY GROUPING SETS ((CASE WHEN monthly_fee >= 206 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('MONTH', end_date)), (CASE WHEN monthly_fee >= 206 THEN 'HIGH' ELSE 'LOW' END), ());
